namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ---------------------------------------------------------------
    // CalculateTotal – DataRow (inline compile-time data)
    // ---------------------------------------------------------------

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "100% tax rate")]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ---------------------------------------------------------------
    // CalculateTotal – invalid inputs via DataRow
    // ---------------------------------------------------------------

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ---------------------------------------------------------------
    // ApplyDiscount – DynamicData with IEnumerable<object[]>
    // ---------------------------------------------------------------

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100.00m, 0m,   100.00m],  // No discount
        [100.00m, 10m,  90.00m],   // 10% off
        [100.00m, 50m,  50.00m],   // Half price
        [100.00m, 100m, 0.00m],    // Free
        [49.99m,  25m,  37.4925m], // Fractional result
        [0.00m,   50m,  0.00m],    // Zero price
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithDynamicData_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // ---------------------------------------------------------------
    // ApplyDiscount – DynamicData from a method (allows display names)
    // ---------------------------------------------------------------

    public static IEnumerable<object[]> InvalidDiscountData()
    {
        yield return [-1m,  "Discount below 0"];
        yield return [101m, "Discount above 100"];
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataSourceType.Method,
        DynamicDataDisplayName = nameof(GetInvalidDiscountDisplayName))]
    public void ApplyDiscount_InvalidDiscount_Throws(
        decimal discountPercent, string _scenario)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }

    public static string GetInvalidDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => $"{methodInfo.Name}: {data[1]}";

    // ---------------------------------------------------------------
    // FormatPrice – DataRow for string output verification
    // ---------------------------------------------------------------

    [TestMethod]
    [DataRow(19.99, "$",  "$19.99",  DisplayName = "Dollar format")]
    [DataRow(19.99, "€",  "€19.99",  DisplayName = "Euro format")]
    [DataRow(5.5,   "$",  "$5.50",   DisplayName = "Pads to two decimals")]
    [DataRow(0.0,   "£",  "£0.00",   DisplayName = "Zero with pound sign")]
    public void FormatPrice_WithDataRow_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}
